def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dynamic programming table with -1
    dp = [[-1] * (N + 1) for _ in range(N + 1)]

    # Fill the dp table
    for i in range(N + 1):
        for j in range(N + 1):
            if i == j == 0:
                dp[i][j] = 0
            elif i == 0 and j > 0:
                dp[i][j] = max(dp[i][j - 1], grid_values[j - 1][2])
            elif j == 0 and i > 0:
                dp[i][j] = max(dp[i - 1][j], grid_values[i - 1][2])
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], grid_values[i * N + j][2])

    return dp[N][N]

